SELECT tenant_id FROM (
 (SELECT DISTINCT p.tenant_id FROM member_cycle_policy p WHERE p.tenant_id>#{after} AND p.effective_from<=#{at}
   AND (SELECT m.cycle_due_at FROM member_record m FORCE INDEX(ix_member_cycle_due) WHERE m.tenant_id=p.tenant_id ORDER BY m.tenant_id,m.cycle_due_at LIMIT 1)<=#{at}
   ORDER BY p.tenant_id LIMIT #{limit})
 UNION
 (SELECT tenant_id FROM member_cycle_policy WHERE rolled_out=FALSE AND tenant_id>#{after} ORDER BY tenant_id LIMIT #{limit})
) t ORDER BY tenant_id LIMIT #{limit}

SELECT COUNT(*) due,MIN(m.cycle_due_at) oldest_due FROM (SELECT DISTINCT tenant_id FROM member_cycle_policy WHERE effective_from<=#{at}) p
JOIN member_record m FORCE INDEX(ix_member_cycle_due) ON m.tenant_id=p.tenant_id AND m.cycle_due_at<=#{at}
LEFT JOIN member_work_retry r ON r.tenant_id=m.tenant_id AND r.lane='cycles' AND r.item_id=m.member_id WHERE
